function badgeClass(status) {
  if (/完成|已收文|成功/.test(status)) return "ok";
  if (/異常|失敗|退回/.test(status)) return "issue";
  if (/待|等待/.test(status)) return "wait";
  return "info";
}

function showToast(message) {
  const toast = document.querySelector("#toast");
  toast.textContent = message;
  toast.classList.add("show");
  window.setTimeout(() => toast.classList.remove("show"), 2400);
}

function confirmOperation(title, body) {
  if (typeof window.confirm !== "function") return true;
  return window.confirm(`${title}\n\n${body}`);
}

function requireTypedConfirm(title, body, phrase) {
  if (typeof window.prompt !== "function") return true;
  const input = window.prompt(`${title}\n\n${body}\n\n請輸入「${phrase}」以繼續。`);
  return input === phrase;
}

function isValidFutureOrToday(dateText) {
  if (!dateText) return false;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const date = new Date(`${dateText}T00:00:00`);
  return !Number.isNaN(date.getTime()) && date >= today;
}

function hasMinimumText(value, minLength = 6) {
  return String(value || "").trim().length >= minLength;
}

function stableHash(value) {
  const text = typeof value === "string" ? value : JSON.stringify(value);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `SHA256-LOCAL-${(hash >>> 0).toString(16).padStart(8, "0").toUpperCase()}`;
}

function downloadTextFile(fileName, content, type = "application/json;charset=utf-8") {
  const blob = new Blob([content], { type });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.click();
  URL.revokeObjectURL(url);
}

async function downloadBinaryFile(path, fallbackFileName, options = {}) {
  const { headers: optionHeaders = {}, ...fetchOptions } = options;
  const headers = { ...optionHeaders };
  if (isHeaderSafeToken(authState?.token)) headers.Authorization = `Bearer ${authState.token}`;
  const response = await fetch(`${backendApiBase}${path}`, { ...fetchOptions, headers, cache: "no-store" });
  if (!response.ok) {
    const raw = await response.text();
    throw new Error(raw.slice(0, 160) || `HTTP ${response.status}`);
  }
  const blob = await response.blob();
  const disposition = response.headers.get("Content-Disposition") || "";
  const fileNameMatch = disposition.match(/filename="?([^"]+)"?/i);
  const fileName = fileNameMatch ? decodeURIComponent(fileNameMatch[1]) : fallbackFileName;
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.click();
  URL.revokeObjectURL(url);
  return { fileName, size: blob.size, type: blob.type };
}

function blockOperation(message, auditFn = null, auditTitle = "操作防呆阻擋") {
  if (auditFn) auditFn(auditTitle, message);
  showToast(message);
  return false;
}

function clearLogWithConfirm(log, renderFn, label) {
  if (!log.length) return showToast(`目前沒有可清除的${label}。`);
  if (!confirmOperation(`確認清除${label}`, "此動作只清除目前畫面的操作軌跡顯示，不會刪除正式 audit log；清除後此畫面無法還原。")) return;
  log.length = 0;
  renderFn();
  showToast(`已清除畫面上的${label}。`);
}

let uiUsageSummary = {
  sessions: 0,
  mobileSessions: 0,
  guidanceSessions: 0,
  mobileRatio: 0,
  guidanceRate: 0,
  source: "尚未載入"
};
const uiUsageRouteTimestamps = new Map();

function uiDeviceClass() {
  const width = Math.max(Number(window.innerWidth || 0), Number(document.documentElement?.clientWidth || 0));
  if (width <= 720) return "mobile";
  if (width <= 1024) return "tablet";
  return "desktop";
}

function uiUsageSessionId() {
  const userId = String(authState?.user?.id || "anonymous").replace(/[^A-Za-z0-9_-]/g, "").slice(0, 40) || "anonymous";
  const key = `edoc-ui-session:${userId}`;
  let value = sessionStorage.getItem(key) || "";
  if (!/^[A-Za-z0-9_-]{12,80}$/.test(value)) {
    const random = globalThis.crypto?.randomUUID?.().replaceAll("-", "") || `${Date.now()}${Math.random().toString(16).slice(2)}`;
    value = `uis_${random}`.slice(0, 72);
    sessionStorage.setItem(key, value);
  }
  return value;
}

function trackUiUsage(eventType, metadata = {}) {
  if (!hasAuthenticatedBackendSession()) return;
  const allowedEvents = new Set(["session_started", "route_view", "guidance_used", "search_result"]);
  if (!allowedEvents.has(eventType)) return;
  const sessionId = uiUsageSessionId();
  const sessionMarker = `edoc-ui-session-recorded:${authState?.user?.id || "user"}:${sessionId}`;
  if (eventType !== "session_started" && sessionStorage.getItem(sessionMarker) !== "true") {
    void trackUiUsage("session_started", { route: activeRouteTarget });
  }
  if (eventType === "session_started") {
    if (sessionStorage.getItem(sessionMarker) === "true") return;
    sessionStorage.setItem(sessionMarker, "true");
  }
  const nowValue = Date.now();
  if (eventType === "route_view") {
    const route = String(metadata.route || "dashboard");
    const last = uiUsageRouteTimestamps.get(route) || 0;
    if (nowValue - last < 10 * 60 * 1000) return;
    uiUsageRouteTimestamps.set(route, nowValue);
  }
  const payload = {
    eventType,
    sessionId,
    deviceClass: uiDeviceClass(),
    route: String(metadata.route || activeRouteTarget || "dashboard").slice(0, 40),
    resultEmpty: metadata.resultEmpty === true,
    resultCount: Math.max(0, Math.min(1000, Number(metadata.resultCount || 0)))
  };
  void backendRequest("/ui-usage", { method: "POST", body: JSON.stringify(payload) }).catch(() => {});
}

async function loadUiUsageSummary(silent = true) {
  try {
    const result = await backendRequest("/ui-usage/summary");
    uiUsageSummary = {
      sessions: Number(result.sessions || 0),
      mobileSessions: Number(result.mobileSessions || 0),
      guidanceSessions: Number(result.guidanceSessions || 0),
      mobileRatio: Number(result.mobileRatio || 0),
      guidanceRate: Number(result.guidanceRate || 0),
      source: result.source || "近 30 日匿名操作事件"
    };
    renderUxHealthMetrics();
  } catch (error) {
    if (!silent) showToast(`使用體驗指標載入失敗：${error.message}`);
  }
}

function setView(target) {
  if (!isRouteAllowed(target)) target = "dashboard";
  activeRouteTarget = target;
  document.body.dataset.activeRoute = target;
  const viewTarget = target === "contractSeal" ? "electronicSeal" : target;
  document.querySelectorAll(".view").forEach((view) => view.classList.toggle("active", view.id === viewTarget));
  document.querySelectorAll(".nav-item").forEach((item) => {
    const active = item.dataset.target === target;
    item.classList.toggle("active", active);
    if (active) item.setAttribute("aria-current", "page");
    else item.removeAttribute("aria-current");
  });
  document.querySelectorAll("[data-more-nav-target]").forEach((item) => {
    const active = item.dataset.moreNavTarget === target;
    item.classList.toggle("active", active);
    if (active) item.setAttribute("aria-current", "page");
    else item.removeAttribute("aria-current");
  });
  const activeNavItem = document.querySelector(`.nav-item[data-target="${target}"]`);
  const navList = activeNavItem?.closest(".nav-list");
  if (activeNavItem && navList && window.matchMedia("(max-width: 720px)").matches) {
    window.requestAnimationFrame(() => {
      const left = activeNavItem.offsetLeft - ((navList.clientWidth - activeNavItem.offsetWidth) / 2);
      navList.scrollTo({ left: Math.max(0, left), behavior: "smooth" });
    });
  }
  document.querySelector("#pageTitle").textContent = simpleRouteTitle(target);
  document.querySelector("#pageEyebrow").textContent = simpleRouteEyebrow(target);
  updateHeaderStatus();
  if (target === "approvalLog" && hasAuthenticatedBackendSession()) void loadApprovalProgressFromBackend();
  if (target === "archive" && hasAuthenticatedBackendSession()) void loadArchiveRecordsFromBackend();
  if (target === "contractSeal" || target === "electronicSeal") {
    configureUploadedSealMode(target);
    void initializeUploadedSealWorkspace();
  }
  void loadRouteBackendData(target, true);
  trackUiUsage("route_view", { route: target });
  if (location.hash !== `#${target}`) history.replaceState(null, "", `#${target}`);
}

window.addEventListener("hashchange", () => {
  const target = location.hash.slice(1);
  if (target && titles[target]) setView(target);
});

function activeRole() {
  return workflowRole || authState?.user?.role || "總務";
}

function activeUnit() {
  if (authState?.user?.role === activeRole()) return authState?.user?.unit || roleDataScopes[activeRole()]?.departments?.[0] || "";
  return roleDataScopes[activeRole()]?.departments?.[0] || authState?.user?.unit || "";
}

function headerClockTime() {
  return new Date().toLocaleTimeString("zh-TW", { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
}

function headerTodoCount() {
  return notificationItems.filter((item) => item.status !== "已讀").length;
}

function updateHeaderStatus() {
  const role = activeRole();
  const user = authState?.user;
  const displayName = user?.name || role;
  const title = user?.title || user?.role || role;
  const topInfo = document.querySelector("#topInfo");
  if (topInfo) topInfo.textContent = `${displayName} · ${title} · 即時同步 · ${headerClockTime()}`;

  const todoCount = headerTodoCount();
  const notificationBadge = document.querySelector("#headerNotificationBadge");
  if (notificationBadge) notificationBadge.toggleAttribute("hidden", todoCount <= 0);

  const moduleBadge = document.querySelector("#moduleTodoBadge");
  if (moduleBadge) {
    moduleBadge.textContent = todoCount > 99 ? "99+" : String(todoCount);
    moduleBadge.toggleAttribute("hidden", todoCount <= 0);
  }
}

