  accountLoginLogs.unshift([nowTime(), "sso-test@suiyuecare.com", accountSsoState.provider, "203.0.113.18", "成功"]);
  renderAccounts();
  addAccountAudit("測試 SSO 登入", `${accountSsoState.provider} 回傳使用者宣告、群組與 MFA 狀態。`);
  showToast("SSO 測試登入成功。");
