function currentNotification() {
  return notificationItems.find((item) => item.id === selectedNotificationId) || null;
}

function notificationSourceReference(item = {}) {
  const actionUrl = String(item.actionUrl || "");
  const officialMatch = actionUrl.match(/official-documents\/([^/?#]+)/);
  const rawSourceId = officialMatch?.[1] || item.sourceId || item.source || "";
  let sourceId = String(rawSourceId);
  try {
    sourceId = decodeURIComponent(sourceId);
  } catch (_error) {
    // Keep the opaque source id; malformed percent escapes must not break the notification center.
  }
  const sourceType = item.sourceType || (sourceId.startsWith("OD-") ? "official_document" : "");
  return { sourceId, sourceType };
}

async function openNotificationSource(item = currentNotification()) {
  if (!item) return showToast("找不到通知來源。");
  const { sourceId, sourceType } = notificationSourceReference(item);
  if (item.id && notificationItems.some((notice) => notice.id === item.id) && item.status !== "已讀") {
    await runNotificationAction("read", [item.id]);
  }
  if (sourceType === "official_document" || sourceId.startsWith("OD-")) {
    try {
      const detail = await backendRequest(`/official-documents/${encodeURIComponent(sourceId)}`);
      const index = officialWorkflowItems.findIndex((entry) => entry.id === detail.id);
      if (index >= 0) officialWorkflowItems[index] = detail;
      else officialWorkflowItems.unshift(detail);
      selectedOfficialDocumentId = detail.id;
      selectedWorkflowTaskId = detail.id;
      approvalLogFilter = approvalProgressCategory({ officialDocument: detail, task: { status: detail.current_status } });
      setView(isRouteAllowed("approvalLog") ? "approvalLog" : "notifications");
      renderApprovalLog();
      return;
    } catch (error) {
      return showToast(`案件載入失敗：${error.message}`);
    }
  }
  const flow = buildUnifiedDocumentFlows().find((entry) => (
    entry.id === sourceId
    || entry.sourceId === sourceId
    || entry.sourceNo === sourceId
  ));
  if (flow) return openUnifiedFlowSource(flow.id);
  if (sourceId && (
    internalDispatchItems.some((entry) => entry.id === sourceId)
    || sourceId.startsWith("IDISP-")
    || /internal[_ -]?dispatch|內部派文/i.test(sourceType)
  )) {
    try {
      if (!internalDispatchItems.some((entry) => entry.id === sourceId)) {
        const detail = await backendRequest(`/internal-dispatches/${encodeURIComponent(sourceId)}`);
        internalDispatchItems.unshift(detail);
      }
      selectedInternalDispatchId = sourceId;
      setInboundSection("dispatch");
      setView(isRouteAllowed("inbound") ? "inbound" : "notifications");
      renderInternalDispatchModule();
      return;
    } catch (error) {
      return showToast(`內部派文載入失敗：${error.message}`);
    }
  }
  showToast("這則通知尚未提供可開啟的來源案件。");
}

function selectedNotificationIds() {
  const checked = [...document.querySelectorAll(".notification-check:checked")].map((item) => item.value);
  return checked.length ? checked : selectedNotificationId ? [selectedNotificationId] : [];
}

function filteredNotifications() {
  const term = notificationSearchTerm.trim().toLowerCase();
  return notificationItems.filter((item) => {
    const overdue = /逾期|退回|補正|失敗|到期/.test(`${item.type || ""}${item.title || ""}${item.body || ""}`);
    const needsAttention = item.status !== "已讀" || overdue;
    const matchFilter = notificationFilter === "my_unread_overdue"
      ? notificationRelatedToCurrentUser(item) && needsAttention
      : notificationFilter === "overdue"
        ? notificationRelatedToCurrentUser(item) && overdue
        : notificationFilter === "all"
      || item.type === notificationFilter
      || item.status === notificationFilter
      || reminderItems(notificationFilter).some((reminder) => reminder.source === item.id || reminder.title === item.title || reminder.source === item.source);
    const haystack = `${item.title} ${item.type} ${item.target} ${item.channel} ${item.status} ${item.source} ${item.body}`.toLowerCase();
    return matchFilter && (!term || haystack.includes(term));
  });
}

function notificationRelatedToCurrentUser(item = {}) {
  if (hasAuthenticatedBackendSession()) return true;
  const targets = [authState?.user?.name, authState?.user?.role, authState?.user?.unit, activeRole()]
    .filter(Boolean)
    .map((value) => String(value).trim());
  const target = String(item.target || "").trim();
  return !target || target === "系統" || targets.some((value) => target === value || target.includes(value) || value.includes(target));
}

function reminderItems(category) {
  const unread = notificationItems.filter((item) => item.status !== "已讀");
  const flowReminders = visibleUnifiedDocumentFlows().filter(isUnifiedFlowTodo);
  const today = [
    ...unread.filter((item) => ["收文", "待清稿", "逾期查核"].includes(item.type)),
    ...flowReminders.filter((flow) => !flow.isIssue).map((flow) => unifiedFlowReminder(flow, "文件待辦"))
  ];
  const dueSoon = [
    ...unread.filter((item) => ["逾期查核", "Token 到期"].includes(item.type)),
    ...flowReminders.filter((flow) => /待確認|待用印|待簽核|待審核|待分派/.test(flow.status)).map((flow) => unifiedFlowReminder(flow, "即將到期")),
    ...trackingCases.filter((item) => ["逾期提醒", "未收確認"].includes(item.status)).map((item) => ({
      id: `REM-${item.id}`,
      type: item.status,
      title: item.title,
      target: item.owner,
      status: item.status,
      source: item.id,
      body: item.note
    }))
  ];
  const returned = [
    ...unread.filter((item) => /退回|補正/.test(`${item.type}${item.title}${item.body}`)),
    ...flowReminders.filter((flow) => /退回|補正/.test(`${flow.status}${flow.currentStep}`)).map((flow) => unifiedFlowReminder(flow, "退回補正")),
    ...trackingCases.filter((item) => item.status === "退回補正").map((item) => ({
      id: `REM-${item.id}`,
      type: "退回補正",
      title: item.title,
      target: item.owner,
      status: item.status,
      source: item.id,
      body: item.note
    }))
  ];
  const failed = [
    ...unread.filter((item) => item.type === "交換失敗"),
    ...flowReminders.filter((flow) => /失敗|異常|未收/.test(`${flow.status}${flow.currentStep}${flow.summary}`)).map((flow) => unifiedFlowReminder(flow, "交換失敗"))
  ];
  const buckets = { today, dueSoon, returned, failed };
  return buckets[category] || [];
}

function renderNotificationSummary() {
  const labels = {
    my_unread_overdue: "我的未讀與逾期",
    all: "全部通知",
    未讀: "我的未讀",
    overdue: "我的逾期",
    today: "今天要處理",
    dueSoon: "即將逾期",
    returned: "已退回",
    failed: "交換失敗"
  };
  document.querySelector("#noticeTodayCount").textContent = reminderItems("today").length;
  document.querySelector("#noticeDueSoonCount").textContent = reminderItems("dueSoon").length;
  document.querySelector("#noticeReturnedCount").textContent = reminderItems("returned").length;
  document.querySelector("#noticeFailedCount").textContent = reminderItems("failed").length;
  document.querySelector("#reminderActiveLabel").textContent = labels[notificationFilter] || labels.all;
  document.querySelectorAll("[data-reminder-filter]").forEach((card) => {
    card.classList.toggle("active", card.dataset.reminderFilter === notificationFilter);
  });
  document.querySelectorAll("[data-notification-filter]").forEach((button) => {
    button.classList.toggle("active", button.dataset.notificationFilter === notificationFilter);
    button.setAttribute("aria-pressed", String(button.dataset.notificationFilter === notificationFilter));
  });
  renderReminderLanes();
}

function renderReminderLanes() {
  const lanes = [
    ["today", "今天要處理"],
    ["dueSoon", "即將逾期"],
    ["returned", "已退回"],
    ["failed", "交換失敗"]
  ];
  document.querySelector("#reminderLanes").innerHTML = lanes.map(([key, title]) => {
    const items = reminderItems(key).slice(0, 4);
    return `
      <section class="reminder-lane">
        <h4>${title}</h4>
        ${items.length ? items.map((item) => `
          <article class="reminder-task ${key === "failed" || key === "dueSoon" || key === "returned" ? "issue" : ""}">
            <strong>${escapeHtml(item.title)}</strong>
            <span>${escapeHtml(item.type)} · ${escapeHtml(item.target || "系統")}</span>
            <p>${escapeHtml(item.body)}</p>
            <button class="text-button" type="button" data-reminder-open="${escapeHtml(item.id)}" data-reminder-source="${escapeHtml(item.source || "")}">開啟案件</button>
          </article>
        `).join("") : `<article class="reminder-task"><strong>目前沒有待辦</strong><p>此分類暫無需要處理的提醒。</p></article>`}
      </section>
    `;
  }).join("");
  document.querySelectorAll("[data-reminder-open]").forEach((button) => {
    button.addEventListener("click", () => {
      const item = notificationItems.find((notice) => notice.id === button.dataset.reminderOpen)
        || notificationItems.find((notice) => notice.source === button.dataset.reminderSource)
        || { id: button.dataset.reminderOpen, source: button.dataset.reminderSource };
      void openNotificationSource(item);
    });
  });
}

function renderNotificationRows() {
  const rows = filteredNotifications();
  if (!rows.some((item) => item.id === selectedNotificationId)) selectedNotificationId = rows[0]?.id || "";
  document.querySelector("#notificationCount").textContent = `${rows.length} 則`;
  const rowsTarget = document.querySelector("#notificationRows");
  rowsTarget.closest("table")?.classList.toggle("is-empty", rows.length === 0);
  rowsTarget.innerHTML = rows.length ? rows.map((item) => `
    <tr class="${item.id === selectedNotificationId ? "selected-row" : ""}">
      <td><input class="notification-check" type="checkbox" value="${escapeHtml(item.id)}" aria-label="選取 ${escapeHtml(item.title)}" /></td>
      <td><button class="text-button row-select" type="button" data-notification-select="${escapeHtml(item.id)}">${escapeHtml(item.title)}</button><small>${escapeHtml(item.source)} · ${escapeHtml(item.priority)}</small></td>
      <td>${escapeHtml(item.type)}</td>
      <td>${escapeHtml(item.target)}</td>
      <td>${escapeHtml(item.channel)}</td>
      <td><span class="badge ${safeHtmlClassToken(badgeClass(item.status), "info")}">${escapeHtml(item.status)}</span></td>
      <td>
        <div class="row-actions">
          <button class="segment" type="button" data-notification-open="${escapeHtml(item.id)}">開啟</button>
          <button class="segment" type="button" data-notification-action="read" data-notification-id="${escapeHtml(item.id)}">已讀</button>
          <button class="segment" type="button" data-notification-action="send" data-notification-id="${escapeHtml(item.id)}">派送</button>
          <button class="segment" type="button" data-notification-action="track" data-notification-id="${escapeHtml(item.id)}">稽催</button>
        </div>
      </td>
    </tr>
  `).join("") : `<tr><td colspan="7"><div class="ux-empty-state"><strong>目前沒有需要你處理的通知</strong><p>新的簽核、退回補正或逾期提醒會自動出現在這裡。</p></div></td></tr>`;
  document.querySelectorAll("[data-notification-select]").forEach((button) => {
    button.addEventListener("click", () => {
      selectedNotificationId = button.dataset.notificationSelect;
      renderNotificationRows();
      renderNotificationDetail();
    });
  });
  document.querySelectorAll("[data-notification-action]").forEach((button) => {
    button.addEventListener("click", () => runNotificationAction(button.dataset.notificationAction, [button.dataset.notificationId]));
  });
  document.querySelectorAll("[data-notification-open]").forEach((button) => {
    button.addEventListener("click", () => {
      const item = notificationItems.find((notice) => notice.id === button.dataset.notificationOpen);
      void openNotificationSource(item);
    });
  });
}

